paint.example:
// client: a cobbled lane through a meadow
const { Vector3 } = kcds.math;
const { Terrain } = kcds.world;

for (let x = 100; x <= 140; x += 2) {
  Terrain.paint(new Vector3(x, 200, 0), 1.5, 'cobblestones', 1);
}

paint.exampleCs:
// client: a cobbled lane through a meadow

for (var x = 100; x <= 140; x += 2)
{
    Terrain.Paint(new Vector3(x, 200, 0), 1.5, "cobblestones", 1);
}

