findPath.example:
// client: is the well reachable on foot from here?
const { Vector3 } = kcds.math;
const { Terrain } = kcds.world;
const me = kcds.players.LocalPlayer.position;

const path = Terrain.findPath(me, new Vector3(2680, 1560, 32));
if (path && path.reaches) {
  console.log(`The well is ${path.points.length} turns away`);
}

findPath.exampleCs:
// client: is the well reachable on foot from here?
if (LocalPlayer.Current?.Position is Vector3 me)
{
    var path = Terrain.FindPath(me, new Vector3(2680, 1560, 32));
    if (path)
    {
        if (path["reaches"])
        {
            Log.Info("The well can be walked to");
        }
    }
}

nearestWalkable.example:
// client: a spot to stand on near the market cross
const { Vector3 } = kcds.math;
const { Terrain } = kcds.world;

const spot = Terrain.nearestWalkable(new Vector3(2675, 1562, 30), 10);
if (spot) {
  console.log(`Stand at ${spot.x.toFixed(1)} ${spot.y.toFixed(1)} ${spot.z.toFixed(1)}`);
}

nearestWalkable.exampleCs:
// client: a spot to stand on near the market cross
var spot = Terrain.NearestWalkable(new Vector3(2675, 1562, 30), 10);
if (spot != null)
{
    Log.Info($"Stand at {spot.X:F1} {spot.Y:F1} {spot.Z:F1}");
}

materials.exampleCs:
// client
var names = Terrain.Materials().Keys;
Log.Info($"Ground materials: {string.Join(", ", names)}");

edits.example:
// client
for (const edit of kcds.world.Terrain.edits().reverse()) {
  edit.undo();
}

edits.exampleCs:
// client
foreach (var edit in Terrain.Edits().Call("reverse"))
{
    edit.Call("undo");
}
